INSERT INTO posts (title, slug, topic, content, image_url) VALUES ('Musk Favorites', 'musk-favorites', 'MUSK', 'A luxurious musk fragrance set featuring three of Ibraq’s most loved and distinctive musk scents. Inspired by moments of the day, this elegant collection blends soft musk with delicate notes that feel fresh, radiant, and comforting throughout the day. Perfect for everyday wear or as a thoughtful gift for musk lovers. Main Perfumes (75 mL): Al Qamar MuskAl Shams MuskAl Fajr Musk Mini Musk Collection (10 mL): Al Qamar MuskAl Shams MuskAl Fajr Musk', 'https://cdn.shopify.com/s/files/1/0795/2682/2173/files/NAWeb_Artboard1copy6_1.png?v=1773406068');
INSERT INTO posts (title, slug, topic, content, image_url) VALUES ('Musk Selection', 'musk-selection', 'MUSK', 'A luxurious musk fragrance set featuring a curated selection. Designed for musk lovers who enjoy soft, elegant fragrances that feel fresh and comforting throughout the day. Delicate fruity and powdery notes blend with smooth musk, creating a balanced scent experience perfect for daily wear or as a thoughtful gift. Main Perfumes (75 mL): Pomegranate MuskPowder MuskAl Qamar Musk Mini Musk Collection (10 mL): Pomegranate MuskPowder MuskAl Qamar Musk', 'https://cdn.shopify.com/s/files/1/0795/2682/2173/files/NA_Web_Artboard_1_copy_8.png?v=1773406085');
