INSERT INTO posts (title, slug, topic, content, image_url) VALUES ('DIAMOND GREY BOX 3 IN 1', 'diamond-grey-box-3-in-1', 'Fragrance', 'The luxurious shades of gray come together in a blend of elegance and tranquility.  The collection includes White Regent with its refined purity, Emerald with its captivating warmth, and Gray with its enchanting mystery. A complete experience that embodies serenity of the senses and offers a presence of refined grace that never fades with time.      Grey Box (75 mL):    White Regent   Emerald Soul  Grey Pear', 'https://cdn.shopify.com/s/files/1/0795/2682/2173/files/DIAMONDGREYBOX3IN1_2.webp?v=1772099006');
