INSERT INTO posts (title, slug, topic, content, image_url) VALUES ('Mexican Tobacco All Over Spray', 'mexican-tobacco-all-over-spray', 'Fragrance', 'Intense. Spicy. Deeply seductive. Mexican Tobacco All Over Spray captures the raw warmth of rich tobacco infused with bold, spicy undertones. Inspired by earthy landscapes and fiery character, this fragrance is crafted for those who prefer powerful scents with unmistakable presence. From the first spray, Mexican Tobacco unfolds with a smoky depth balanced by subtle sweetness and spice, leaving a trail that feels confident, magnetic, and unapologetically bold. Designed as an all-over spray, it ca...', 'https://cdn.shopify.com/s/files/1/0795/2682/2173/files/mexicantobaccoallover.webp?v=1772100358');